// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        address actor,
        uint64 number,
        uint64 timestamp,
        uint256 basefee,
        bytes32 hash,
        uint64 sequenceNumber,
        bytes32 batcherHash,
        uint256 l1FeeOverhead,
        uint256 l1FeeScalar
    ) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok;
        try c.setL1BlockValues(number, timestamp, basefee, hash, sequenceNumber, batcherHash, l1FeeOverhead, l1FeeScalar) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.basefee() == basefee);
    }
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    function testSetBlock(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) external {
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(
                c.setL1BlockValues.selector,
                _number, _timestamp, _basefee, _hash,
                _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar
            )
        );
        assert(ok);
    }
}
